class _Cursor:
    """Stand-in for a DB-API cursor with a per-call latency cost."""
    def __init__(self, table):
        self.table = table
        self.rows = []
    def execute(self, sql, params=()):
        # Simulate round-trip + planning cost per statement.
        _ = sum(range(2000))
        if "ANY" in sql or " IN " in sql:
            wanted = set(params[0])
            self.rows = [r for r in self.table if r[0] in wanted]
        else:
            self.rows = [r for r in self.table if r[0] == params[0]]
    def fetchone(self):
        return self.rows[0] if self.rows else None
    def fetchall(self):
        return list(self.rows)

def solve(table, ids):
    cur = _Cursor(table)
    names = {}
    for i in ids:
        cur.execute("SELECT id, name FROM users WHERE id = %s", (i,))
        row = cur.fetchone()
        if row:
            names[i] = row[1]
    return names
